from fastapi import APIRouter, Depends, HTTPException
from langgraph.checkpoint.base import BaseCheckpointSaver

router = APIRouter(prefix="/agent/graph")

@router.get("/checkpoints/{checkpoint_id}/state")
async def get_graph_checkpoint_state(
    checkpoint_id: str,
    current_user: User = Depends(get_current_user),
    checkpointer: BaseCheckpointSaver = Depends(get_graph_checkpointer)
):
    config = {"configurable": {"checkpoint_id": checkpoint_id}}
    state_tuple = await checkpointer.aget_tuple(config)
    if not state_tuple:
        raise HTTPException(status_code=404, detail="Graph checkpoint not found")

    metadata = state_tuple.metadata or {}
    if metadata.get("tenant_id") != current_user.tenant_id:
        raise HTTPException(status_code=404, detail="Graph checkpoint not found")

    return {
        "checkpoint_id": checkpoint_id,
        "values": state_tuple.checkpoint.get("channel_values", {}),
        "next": state_tuple.next,
        "metadata": state_tuple.metadata
    }
